- Ese ntibagenda ku isi bakareba uko iherezo ryagenze? (أَوَلَمْ يَسِيرُوا فِي الْأَرْضِ فَيَنظُرُوا كَيْفَ كَانَ عَاقِبَةُ) 30:9; 35:44; 40:21; 40:82; 47:10
- Ubustani butembwamo n’inzuzi, bazabamo ubuziraherezo. (جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا أَبَدًا) 4:57; 4:122; 5:119; 64:9; 65:11
- Uinjiza ijoro mu manywa, ukwinjiza amanywa mu ijoro. (تُولِجُ اللَّيْلَ فِي النَّهَارِ وَتُولِجُ النَّهَارَ فِي اللَّيْلِ) 3:27; 22:61; 31:29; 35:13; 57:6
- Ibyo mu ijuru n’ibyo mu isi byose bihimiriza Allah. (سَبَّحَ لِلَّهِ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ) 59:1; 61:1; 62:1; 64:1
- Mugaragarire Allah, nta yindi mana mufite itari We. Ese ntimutinya? (اعْبُدُوا اللَّهَ مَا لَكُم مِّنْ إِلَهٍ غَيْرُهُ أَفَلَا) 7:65; 11:84; 23:23; 23:32
- Twabwiye abamarayika ngo: Nimumirambire kuri Adamu, baramirambye uretse Ibilisi. (وَإِذْ قُلْنَا لِلْمَلَائِكَةِ اسْجُدُوا لِآدَمَ فَسَجَدُوا إِلَّا إِبْلِيسَ) 2:34; 17:61; 18:50; 20:116
- Allah azi ibiri mu ijuru no ku isi. (اللَّهُ وَيَعْلَمُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ) 3:29; 5:97; 49:16; 58:7
- Ubustani butembwamo n’inzuzi, bazabamo ubuziraherezo, kandi ibyo. (جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا وَذَلِكَ) 4:13; 5:85; 9:89; 57:12
- Igihano cye kiri kwa Nyagasani we, kandi nta bwoba buri kuri bo, kandi bo. (أَجْرُهُ عِندَ رَبِّهِ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ) 2:112; 2:262; 2:274; 2:277
- Kwa Nyagasani we, kandi nta bwoba buri kuri bo, kandi ntibazababara. (عِندَ رَبِّهِ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ) 2:112; 2:262; 2:274; 2:277
- Uwayobowe, ari we ubwe ayoborwa, n’uyobye. (فَمَنِ اهْتَدَى فَإِنَّمَا يَهْتَدِي لِنَفْسِهِ وَمَن ضَلَّ) 10:108; 17:15; 27:92
- Ari we ubwe ayoborwa, n’uyobye, ari we ubwe ayobya. (يَهْتَدِي لِنَفْسِهِ وَمَن ضَلَّ فَإِنَّمَا يَضِلُّ عَلَيْهَا) 10:108; 17:15; 39:41
- Kuki hatamanuriwe ikimenyetso cyaturutse kwa Nyagasani we? Vuga ngo: Mu by’ukuri. (لَوْلَا أُنزِلَ عَلَيْهِ آيَةٌ مِّن رَّبِّهِ فَقُلْ إِنَّمَا) 10:20; 13:27; 29:50
- Abemeye kandi bakora ibyiza, bazagororwa ibihembo bitazima. (الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ لَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍ) 41:8; 84:25; 95:6
- Ukura ibizima mu byapfuye, kandi ukura ibyapfuye mu bizima. (وَتُخْرِجُ الْحَيَّ مِنَ الْمَيِّتِ وَتُخْرِجُ الْمَيِّتَ مِنَ الْحَيِّ) 3:27; 10:31; 30:19
- Uwo adacira urubanza nk’uko Allah yamanuye, abo ni bo. (وَمَن لَّمْ يَحْكُم بِمَا أَنزَلَ اللَّهُ فَأُولَئِكَ هُمُ) 5:44; 5:45; 5:47
- Yaremye ijuru n’isi n’ibiri hagati yabyo mu minsi itandatu. (خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ وَمَا بَيْنَهُمَا فِي سِتَّةِ أَيَّامٍ) 25:59; 32:4; 50:38
- Mu by’ukuri, Allah ni Uwimbabazi ku bantu, ariko benshi. (إِنَّ اللَّهَ لَذُو فَضْلٍ عَلَى النَّاسِ وَلَكِنَّ أَكْثَرَ) 2:243; 10:60; 40:61
- Allah ntiyabarenganyije, ahubwo bo ubwabo bariyarenganyije. (فَمَا كَانَ اللَّهُ لِيَظْلِمَهُمْ وَلَكِن كَانُوا أَنفُسَهُمْ يَظْلِمُونَ) 9:70; 29:40; 30:9
- Azabababarira ibyaha byanyu, akanabinjiza mu busitani butembwamo n’inzuzi. (عَنكُمْ سَيِّئَاتِكُمْ وَلَأُدْخِلَنَّكُمْ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ) 5:12; 64:9; 66:8
- Yababujije ibyapfuye, amaraso, inyama z’ingurube, n’ibyabagwe izina ritari irya Allah. (حَرَّمَ عَلَيْكُمُ الْمَيْتَةَ وَالدَّمَ وَلَحْمَ الْخِنزِيرِ وَمَا أُهِلَّ) 2:173; 5:3; 16:115
- Mu by’ukuri, ndatinya, ninyigometse kwa Nyagasani wanjye, ibihano by’umunsi munini. (إِنِّي أَخَافُ إِنْ عَصَيْتُ رَبِّي عَذَابَ يَوْمٍ عَظِيمٍ) 6:15; 10:15; 39:13
- Ariko nyuma y’uko ubumenyi bwabagezeho, kubera ishyari hagati yabo. (إِلَّا مِن بَعْدِ مَا جَاءَهُمُ الْعِلْمُ بَغْيًا بَيْنَهُمْ) 3:19; 42:14; 45:17
- Baramba amasengesho, kandi batanga ibyo twabahaye, mu ibanga no mu ngaruka. (وَأَقَامُوا الصَّلَاةَ وَأَنفَقُوا مِمَّا رَزَقْنَاهُمْ سِرًّا وَعَلَانِيَةً) 13:22; 14:31; 35:29
- Ese twasenga ibitari Allah, ibyo bitadufasha kandi bitaduhungabanya? (مِن دُونِ اللَّهِ مَا لَا يَنفَعُنَا وَلَا يَضُرُّنَا) 6:71; 10:106; 25:55
- Bemerera ibyo yahishuriwe, n’ibyo yahishuriwe mbere y’uko aza. (يُؤْمِنُونَ بِمَا أُنزِلَ إِلَيْكَ وَمَا أُنزِلَ مِن قَبْلِكَ) 2:4; 4:60; 4:162
- Ese ntureba ko Allah amanura amazi mu ijuru? (أَلَمْ تَرَ أَنَّ اللَّهَ أَنزَلَ مِنَ السَّمَاءِ مَاءً) 22:63; 35:27; 39:21
- Iyo ashoye ikintu, ubwo abwira ngo: Ba, kikaba. (قَضَى أَمْرًا فَإِنَّمَا يَقُولُ لَهُ كُن فَيَكُونُ) 3:47; 19:35; 40:68
- No ku Banyamadyani (twohereje) mwene wabo Shu’aybu. Yavuze ati: Yemwe bantu banjye! Mugaragarire Allah. (وَإِلَى مَدْيَنَ أَخَاهُمْ شُعَيْبًا قَالَ يَاقَوْمِ اعْبُدُوا اللَّهَ) 7:85; 11:84; 29:36
- Ibyo ni bimwe mu bitarambwa, tubihishurira; ntiwabizi. (ذَلِكَ مِنْ أَنْبَاءِ الْغَيْبِ نُوحِيهِ إِلَيْكَ وَمَا كُنتَ) 3:44; 11:49; 12:102
- Iyo igihe cyabo kigeze, ntibagishobora kurinda n’isaha, cyangwa ngo kikibanzirize. (فَإِذَا جَاءَ أَجَلُهُمْ لَا يَسْتَأْخِرُونَ سَاعَةً وَلَا يَسْتَقْدِمُونَ) 7:34; 10:49; 16:61
- Ntimukurikize inzira za Shitani, mu by’ukuri ni umwanzi wanyu ugaragara. (وَلَا تَتَّبِعُوا خُطُوَاتِ الشَّيْطَانِ إِنَّهُ لَكُمْ عَدُوٌّ مُّبِينٌ) 2:168; 2:208; 6:142
- Mu bantu hari abajya impaka kuri Allah nta bumenyi bafite. (وَمِنَ النَّاسِ مَن يُجَادِلُ فِي اللَّهِ بِغَيْرِ عِلْمٍ) 22:3; 22:8; 31:20
- Allah aha uwo ashaka, kandi Allah ni Uwimbabazi bihebuje. (اللَّهِ يُؤْتِيهِ مَن يَشَاءُ وَاللَّهُ ذُو الْفَضْلِ الْعَظِيمِ) 57:21; 57:29; 62:4
- Buri muntu azahabwa ibihembo bye kubera ibyo yakoze, kandi ntabazarenganywa. (تُوَفَّى كُلُّ نَفْسٍ مَّا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَ) 2:281; 3:25; 3:161
- Ntimwicira ubuzima Allah yabujije, keretse ku mpamvu ikwiriye. (وَلَا تَقْتُلُوا النَّفْسَ الَّتِي حَرَّمَ اللَّهُ إِلَّا بِالْحَقِّ) 6:151; 17:33; 25:68
- Iyo ashoye ikintu, abwira ngo: Ba. (إِذَا قَضَى أَمْرًا فَإِنَّمَا يَقُولُ لَهُ كُن) 3:47; 19:35; 40:68
- Nimwinjire mu marembo y’umuriro wa Jahanamu, muzabamo ubuziraherezo; kandi ni bibi kuba kwa abanyacyubahiro! (فَادْخُلُوا أَبْوَابَ جَهَنَّمَ خَالِدِينَ فِيهَا فَلَبِئْسَ مَثْوَى الْمُتَكَبِّرِينَ) 16:29; 39:72; 40:76
- Ese ntubona abo bahawe igice cy’Igitabo? (أَلَمْ تَرَ إِلَى الَّذِينَ أُوتُوا نَصِيبًا مِّنَ الْكِتَابِ) 3:23; 4:44; 4:51
- Bazagira ubusitani butembwamo n’inzuzi, bazabamo ubuziraherezo. (لَهُمْ جَنَّاتٌ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا) 3:198; 5:119; 9:89
- Yemwe bantu banjye! Ngaho mukore uko mushoboye, nanjye ndakora, muzamenya. (يَاقَوْمِ اعْمَلُوا عَلَى مَكَانَتِكُمْ إِنِّي عَامِلٌ فَسَوْفَ تَعْلَمُونَ) 6:135; 11:93; 39:39
- Uwanyuranya Allah n’Intumwa ye, azabwa umuriro wa Jahanamu, azabamo ubuziraherezo. (اللَّهَ وَرَسُولَهُ فَأَنَّ لَهُ نَارَ جَهَنَّمَ خَالِدًا فِيهَا) 9:63; 72:23
- Twashyize ibikingi ku mitima yabo, kugira ngo batabyumva, n’ubupfumu mu matwi yabo. (عَلَى قُلُومِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِي آذَانِهِمْ وَقْرًا) 17:46; 18:57
- Nta mudugudu twohererejeyo umuburizi, uretse abakire bawo bavuze ngo: Mu by’ukuri, twe. (فِي قَرْيَةٍ مِّن نَّذِيرٍ إِلَّا قَالَ مُتْرَفُوهَا إِنَّا) 34:34; 43:23
- Baravuze bati: Dusabire kwa Nyagasani wawe, atubwire ibyayo. (قَالُوا ادْعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا هِيَ) 2:68; 2:70
- Bazavuga bati: Ni Allah. Vuga ngo: Ibyishimo byose ni ibya Allah! Ariko benshi muri bo. (لَيَقُولُنَّ اللَّهُ قُلِ الْحَمْدُ لِلَّهِ بَلْ أَكْثَرُهُمْ لَا) 29:63; 31:25
- Nta kindi gisubizo cy’abantu be cyari ikindi uretse ngo: Babirukane. (وَمَا كَانَ جَوَابَ قَوْمِهِ إِلَّا أَن قَالُوا أَخْرِجُوهُم) 7:82; 27:56
- Hazaba hari inzuzi zitemba munsi yabyo, bazabamo ubuziraherezo; ibyo ni intsinzi ikomeye. (تَحْتَهَا الْأَنْهَارُ خَالِدِينَ فِيهَا أَبَدًا ذَلِكَ الْفَوْزُ الْعَظِيمُ) 9:100; 64:9
- Abo ni bo bayobowe na Nyagasani wabo, kandi abo ni bo batsinze. (أُولَئِكَ عَلَى هُدًى مِّن رَّبِّهِمْ وَأُولَئِكَ هُمُ الْمُفْلِحُونَ) 2:5; 31:5
- Uwo ibihano bitera isoni bizamugeraho, n’ibihano bihoraho bimugeraho. (مَن يَأْتِيهِ عَذَابٌ يُخْزِيهِ وَيَحِلُّ عَلَيْهِ عَذَابٌ مُّقِيمٌ) 11:39; 39:40
- Nimugende ku isi, murebe uko iherezo ry’abahakanye ryagenze. (فَسِيرُوا فِي الْأَرْضِ فَانظُرُوا كَيْفَ كَانَ عَاقِبَةُ الْمُكَذِّبِينَ) 3:137; 16:36
- Ntabwo bazifuza na rimwe, kubera ibyo intoki zabo zakoze, kandi Allah azi abakiranirwa. (يَتَمَنَّوْهُ أَبَدًا بِمَا قَدَّمَتْ أَيْدِيهِمْ وَاللَّهُ عَلِيمٌ بِالظَّالِمِينَ) 2:95; 62:7
- We azi neza uwabaye mu nzira ye, kandi We azi neza. (هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ وَهُوَ أَعْلَمُ) 53:30; 68:7
- Mu by’ukuri, Allah ni Nyagasani wanjye na Nyagasani wanyu, nimumugaragarire; iyi ni nzira igororotse. (إِنَّ اللَّهَ رَبِّي وَرَبُّكُمْ فَاعْبُدُوهُ هَذَا صِرَاطٌ مُّسْتَقِيمٌ) 3:51; 19:36
- Ni Uwimbabazi ku bantu, ariko benshi muri bo ntibashima. (لَذُو فَضْلٍ عَلَى النَّاسِ وَلَكِنَّ أَكْثَرَهُمْ لَا يَشْكُرُونَ) 10:60; 27:73
- Ntitwaremye ijuru n’isi n’ibiri hagati yabyo, keretse mu kuri no ku gihe kigereranyijwe. (السَّمَاوَاتِ وَالْأَرْضَ وَمَا بَيْنَهُمَا إِلَّا بِالْحَقِّ وَأَجَلٍ مُّسَمًّى) 30:8; 46:3
- Bareke bakomeze kwibwira no gukina, kugeza bahuye n’umunsi wabo bari barasezeranyijwe. (فَذَرْهُمْ يَخُوضُوا وَيَلْعَبُوا حَتَّى يُلَاقُوا يَوْمَهُمُ الَّذِي يُوعَدُونَ) 43:83; 70:42
- Iyo bahuye n’abemera, baravuga ngo: Turagize imana, ariko iyo basigaye bonyine. (وَإِذَا لَقُوا الَّذِينَ آمَنُوا قَالُوا آمَنَّا وَإِذَا خَلَوْا) 2:14; 2:76
- Bashyira mu bikorwa Taurati n’Injili, n’ibyo bahishuriwe na Nyagasani wabo. (أَقَامُوا التَّوْرَاةَ وَالْإِنجِيلَ وَمَا أُنزِلَ إِلَيْهِم مِّن رَّبِّهِمْ) 5:66; 5:68
- Azi iby’imbere yabo n’iby’inyuma yabo, kandi ntibashobora kubimenya byose. (يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلَا يُحِيطُونَ) 2:255; 20:110
- Ni We waremye ijuru n’isi mu minsi itandatu. (وَهُوَ الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ فِي سِتَّةِ أَيَّامٍ) 11:7; 57:4
- Mu by’ukuri, muri ibyo hari ikimenyetso, niba muri abemera. (إِنَّ فِي ذَلِكَ لَآيَةً لَّكُمْ إِن كُنتُم مُّؤْمِنِينَ) 2:248; 3:49
- Niki cyabujije abantu kugira imana, ubwo umuyoboro wabageragaho? (وَمَا مَنَعَ النَّاسَ أَن يُؤْمِنُوا إِذْ جَاءَهُمُ الْهُدَى) 17:94; 18:55
- Bashyira Allah abafatanyabujiji, kugira ngo babazize inzira ye. Vuga ngo: Nimwishimire. (وَجَعَلُوا لِلَّهِ أَندَادًا لِّيُضِلُّوا عَن سَبِيلِهِ قُلْ تَمَتَّعُوا) 14:30; 39:8
- Baratangaje ko umuburizi yabageragaho avuye muri bo, abahakana baravuga bati: Uyu. (وَعَجِبُوا أَن جَاءَهُم مُّنذِرٌ مِّنْهُمْ وَقَالَ الْكَافِرُونَ هَذَا) 38:4; 50:2
- Mu by’ukuri, Nyagasani wawe ni We uzi neza uwabaye mu nzira ye. (إِنَّ رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ) 53:30; 68:7
- Nk’uwo utanga umutungo we kugira ngo abantu bamurebe, kandi ntibemerera Allah. (كَالَّذِي يُنفِقُ مَالَهُ رِئَاءَ النَّاسِ وَلَا يُؤْمِنُ بِاللَّهِ) 2:264; 4:38
- Mutange ibyo twabahaye, mbere y’uko bikubaho. (أَنفِقُوا مِمَّا رَزَقْنَاكُم مِّن قَبْلِ أَن يَأْتِيَ) 2:254; 63:10
- Yabahaye ubushobozi bwo gukoresha ibiri mu ijuru no ku isi. (سَخَّرَ لَكُم مَّا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ) 31:20; 45:13
- Kandi mu by’ukuri, turi mu gushidikanya ku byo utuhamagarira. (وَإِنَّنَا لَفِي شَكٍّ مِّمَّا تَدْعُونَا إِلَيْهِ مُرِيبٍ) 11:62; 14:9
- Mu by’ukuri, Nyagasani wawe araguriza ngo agabanyirize amafunguro uwo ashaka. Mu by’ukuri, We. (إِنَّ رَبَّكَ يَبْسُطُ الرِّزْقَ لِمَن يَشَاءُ وَيَقْدِرُ إِنَّهُ) 17:30; 34:36
- Nyagasani w’ijuru n’isi n’ibiri hagati yabyo, niba muri abemera badashidikanya. (رَبُّ السَّمَاوَاتِ وَالْأَرْضِ وَمَا بَيْنَهُمَا إِن كُنتُم مُّوقِنِينَ) 26:24; 44:7
- Twemeye Allah n’ibyo yahishuriye, n’ibyo yahishuriye. (آمَنَّا بِاللَّهِ وَمَا أُنزِلَ إِلَيْنَا وَمَا أُنزِلَ إِلَى) 2:136; 3:199
- Abarenganye bagwirirwa n’urubemba, bagasanga mu ngo zabo bapfuye. (وَأَخَذَ الَّذِينَ ظَلَمُوا الصَّيْحَةُ فَأَصْبَحُوا فِي دِيَارِهِمْ جَاثِمِينَ) 11:67; 11:94
- Nta cyaha kuri mwe mu byo bakora ku bwe bwabo. (فَلَا جُنَاحَ عَلَيْكُمْ فِيمَا فَعَلْنَ فِي أَنفُسِهِنَّ) 2:234; 2:240
- Nyagasani wawe ni We uzi neza uwabaye mu nzira ye, kandi We. (رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ وَهُوَ) 53:30; 68:7
- N’umwuka (ubyahishuriwe) n’itegeko rye, ku uwo ashaka mu bagaragu be. (بِالرُّوحِ مِنْ أَمْرِهِ عَلَى مَن يَشَاءُ مِنْ عِبَادِهِ) 16:2; 40:15
- Twahaye Isa mwana wa Mariyamu ibimenyetso bigaragara, tukamushyigikira n’Umwuka Wera. (وَآتَيْنَا عِيسَى ابْنَ مَرْيَمَ الْبَيِّنَاتِ وَأَيَّدْنَاهُ بِرُوحِ الْقُدُسِ) 2:87; 2:253
- Kugira ngo aburane hagati yabo ku munsi w’izuka, ibyo batavugaga rumwe. (لَيَحْكُمُ بَيْنَهُمْ يَوْمَ الْقِيَامَةِ فِيمَا كَانُوا فِيهِ) 16:124; 22:69
- Twacyitaye ikibanza, tukamanuriraho amabuye y’ibumba ryatswe. (جَعَلْنَا عَالِيَهَا سَافِلَهَا وَأَمْطَرْنَا عَلَيْهَا حِجَارَةً مِّن سِجِّيلٍ) 11:82; 15:74
- Kimwe kuri bo, urababurira cyangwa utababurira, ntibazemera. (سَوَاءٌ عَلَيْهِمْ أَأَنذَرْتَهُمْ أَمْ لَمْ تُنذِرْهُمْ لَا يُؤْمِنُونَ) 2:6; 36:10
- Usibye abantu, mujye mwifuza urupfu, niba muri abanyakuri. (مِّن دُونِ النَّاسِ فَتَمَنَّوُا الْمَوْتَ إِن كُنتُمْ صَادِقِينَ) 2:94; 62:6
- Allah, nta yindi mana mufite itari We. Ese ntimutinya? (اللَّهَ مَا لَكُم مِّنْ إِلَهٍ غَيْرُهُ أَفَلَا تَتَّقُونَ) 23:23; 23:32
- Yaba twakwerekana kimwe mu byo twabasezeranyije, cyangwa tugukuraho, kuri twe ni ho bazasubira. (وَإِمَّا نُرِيَنَّكَ بَعْضَ الَّذِي نَعِدُهُمْ أَوْ نَتَوَفَّيَنَّكَ فَإِلَيْنَا) 10:46; 40:77
- Baravuze bati: Ese nidupfa tukaba ivumbi n’amagufa, tuzazuka? (قَالُوا أَإِذَا مِتْنَا وَكُنَّا تُرَابًا وَعِظَامًا أَإِنَّا لَمَبْعُوثُونَ) 23:82; 56:47
- Mu by’ukuri, impuhwe zo mu kuboko kwa Allah, aha uwo ashaka, kandi Allah. (إِنَّ الْفَضْلَ بِيَدِ اللَّهِ يُؤْتِيهِ مَن يَشَاءُ وَاللَّهُ) 3:73; 57:29
- Kandi muzasubizwa kwa Uzi ibitagaragara n’ibigaragara, ababwire ibyo mwakoraga. (إِلَى عَالِمِ الْغَيْبِ وَالشَّهَادَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ) 9:105; 62:8
- Yemwe mwemeye! Nimwibuke ingabire ya Allah kuri mwe, igihe. (يَا أَيُّهَا الَّذِينَ آمَنُوا اذْكُرُوا نِعْمَتَ اللَّهِ عَلَيْكُمْ إِذْ) 5:11; 33:9
- Kandi mbere y’uko uza, nta bandi twohereje uretse abagabo twahishuriye. (وَمَا أَرْسَلْنَا مِن قَبْلِكَ إِلَّا رِجَالًا نُّوحِي إِلَيْهِم) 12:109; 16:43
- Azamubabarira ibyaha bye, akamwinjiza mu busitani butembwamo n’inzuzi. (يُكَفِّرْ عَنْهُ سَيِّئَاتِهِ وَيُدْخِلْهُ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا) 64:9; 66:8
- Uwaye indwara cyangwa ari mu rugendo, azuzuza umubare w’indi minsi. (مَّرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِّنْ أَيَّامٍ أُخَرَ) 2:184; 2:185
- Nta kindi bakurikiza keretse ibitekerezo, kandi ntibakoze ikindi keretse guhagarika. (إِن يَتَّبِعُونَ إِلَّا الظَّنَّ وَإِنْ هُمْ إِلَّا يَخْرُصُونَ) 6:116; 10:66
- Hari urugero rwiza rw’uwizeye Allah n’umunsi w’imperuka. (أُسْوَةٌ حَسَنَةٌ لِّمَن كَانَ يَرْجُو اللَّهَ وَالْيَوْمَ الْآخِرَ) 33:21; 60:6
- Ntitwaremye ijuru n’isi n’ibiri hagati yabyo, keretse mu kuri. (وَمَا خَلَقْنَا السَّمَاوَاتِ وَالْأَرْضَ وَمَا بَيْنَهُمَا إِلَّا بِالْحَقِّ) 15:85; 46:3
- Ongera ukuboko kwawe mu kinyabupfu cyawe, kizasohoka kwererana nta kibi. (يَدَكَ فِي جَيْبِكَ تَخْرُجْ بَيْضَاءَ مِنْ غَيْرِ سُوءٍ) 27:12; 28:32
- Agira impuhwe ze ku uwo ashaka, kandi Allah ni Uwimbabazi bihebuje. (يَخْتَصُّ بِرَحْمَتِهِ مَن يَشَاءُ وَاللَّهُ ذُو الْفَضْلِ الْعَظِيمِ) 2:105; 3:74
- Ese ntuzi ko Allah ari We nyir’ubwami bw’ijuru n’isi? (أَلَمْ تَعْلَمْ أَنَّ اللَّهَ لَهُ مُلْكُ السَّمَاوَاتِ وَالْأَرْضِ) 2:107; 5:40
- Icyiza cyose mugira, muzagisanga kwa Allah. (وَمَا تُقَدِّمُوا لِأَنفُسِكُم مِّنْ خَيْرٍ تَجِدُوهُ عِندَ اللَّهِ) 2:110; 73:20
- N’aho uva hose, hindukiriza mu maso yawe Umusigiti Mutagatifu. (وَمِنْ حَيْثُ خَرَجْتَ فَوَلِّ وَجْهَكَ شَطْرَ الْمَسْجِدِ الْحَرَامِ) 2:149; 2:150
- Abo mbere yanyu barashize, kandi ntuzabona impinduka mu migenzo ya Allah. (خَلَوْا مِن قَبْلُ وَلَن تَجِدَ لِسُنَّةِ اللَّهِ تَبْدِيلًا) 33:62; 48:23
- Ufite iby’ijuru n’iby’isi. (الَّذِي لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ) 34:1; 42:53
- Nta gore ritera inda cyangwa ngo ryabyare, keretse ubwo abizi. (وَمَا تَحْمِلُ مِنْ أُنثَى وَلَا تَضَعُ إِلَّا بِعِلْمِهِ) 35:11; 41:47
- Yagize ijoro n’izuba n’ukwezi, buri kimwe kigenda mu gihe kigereranyijwe. (اللَّيْلِ وَسَخَّرَ الشَّمْسَ وَالْقَمَرَ كُلٌّ يَجْرِي لِأَجَلٍ مُّسَمًّى) 35:13; 39:5
- Hazaba hari inzuzi zitemba munsi yabyo, bazabamo ubuziraherezo, kandi ibyo ni ibihembo. (تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا وَذَلِكَ جَزَاءُ) 5:85; 20:76
- Yavuze ati: Oya, ahubwo ubwenge bwanyu bwabateye ikintu; kwihangana ni byiza. (قَالَ بَلْ سَوَّلَتْ لَكُمْ أَنفُسُكُمْ أَمْرًا فَصَبْرٌ جَمِيلٌ) 12:18; 12:83
- Ibyo mu ijuru no ku isi, n’uko Allah. (مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَأَنَّ اللَّهَ) 5:97; 22:64
- Nta ntumwa yabageragaho, batamunseka. (وَمَا يَأْتِيهِم مِّن رَّسُولٍ إِلَّا كَانُوا بِهِ يَسْتَهْزِئُونَ) 15:11; 36:30
- Baravuze bati: Yewe Musa! Ese ni wowe ujya kunyura, cyangwa ni twe tuzajugunya? (قَالُوا يَامُوسَى إِمَّا أَن تُلْقِيَ وَإِمَّا أَن نَّكُونَ) 7:115; 20:65
- Ni We ubaha urupfu, kandi muri mwe hari uzasubizwa mu buzima bubi cyane, kugira. (يَتَوَفَّاكُمْ وَمِنكُم مَّن يُرَدُّ إِلَى أَرْذَلِ الْعُمُرِ لِكَيْ) 16:70; 22:5
- Bazagira ubusitani butembwamo n’inzuzi, bazabamo ubuziraherezo. (رَبِّهِمْ جَنَّاتٌ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا) 3:15; 3:136
- Twashyize ibikingi ku mitima yabo, kugira ngo batabyumva, n’ubupfumu mu matwi yabo. (وَجَعَلْنَا عَلَى قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِي آذَانِهِمْ) 17:46; 18:57
- Mu by’ukuri, isezerano rya Allah ni ukuri, ariko benshi muri bo ntibabizi. (إِنَّ وَعْدَ اللَّهِ حَقٌّ وَلَكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ) 10:55; 28:13
- Ibyo ni uko banyuranyije Allah n’Intumwa ye; kandi uwanyuranya Allah. (ذَلِكَ بِأَنَّهُمْ شَاقُّوا اللَّهَ وَرَسُولَهُ وَمَن يُشَاقِقِ اللَّهَ) 8:13; 59:4
- No ku munsi azabahamagara, ababwire ngo: Hehe abo mumpanganije, abo mwitwaga? (وَيَوْمَ يُنَادِيهِمْ فَيَقُولُ أَيْنَ شُرَكَائِيَ الَّذِينَ كُنتُمْ تَزْعُمُونَ) 28:62; 28:74
- Ese ntibabonye ko Allah, waremye ijuru n’isi, ashobora kurema nkabo? (أَوَلَمْ يَرَوْا أَنَّ اللَّهَ الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ) 17:99; 46:33
- (Uw) waremye abantu mu butaka, hanyuma mu ntanga, hanyuma. (بِالَّذِي خَلَقَكَ مِن تُرَابٍ ثُمَّ مِن نُّطْفَةٍ ثُمَّ) 18:37; 40:67
- Bari kuvuga bati: Nyagasani wacu! Iyo uza kutuhererera intumwa, twakurikiye ibimenyetso byawe. (لَقَالُوا رَبَّنَا لَوْلَا أَرْسَلْتَ إِلَيْنَا رَسُولًا فَنَتَّبِعَ آيَاتِكَ) 20:134; 28:47
- Hanyuma bazasubizwa kwa Nyagasani wabo, ababwire ibyo bakoraga. (ثُمَّ إِلَى رَبِّهِم مَّرْجِعُهُمْ فَيُنَبِّئُهُم بِمَا كَانُوا يَعْمَلُونَ) 6:108; 39:7
- Nta bumenyi bafite ku byo, ntibakurikiza keretse ibitekerezo. (مَّا لَهُم بِذَلِكَ مِنْ عِلْمٍ إِنْ هُمْ إِلَّا) 43:20; 45:24
- Mu by’ukuri, twasanze ba sekuru bacu bari ku idini, kandi twebwe turabakurikiza. (إِنَّا وَجَدْنَا آبَاءَنَا عَلَى أُمَّةٍ وَإِنَّا عَلَى آثَارِهِم) 43:22; 43:23
- Abo bahawe igitabo, ntibatavugaga rumwe, keretse nyuma y’uko ubumenyi bubagezeho. (الَّذِينَ أُوتُوا الْكِتَابَ إِلَّا مِن بَعْدِ مَا جَاءَهُمُ) 3:19; 98:4
- Ubwo Ibrahimu yavuzaga ati: Nyagasani wanjye! Uyu mudugudu ugaragare amahoro. (وَإِذْ قَالَ إِبْرَاهِيمُ رَبِّ اجْعَلْ هَذَا بَلَدًا آمِنًا) 2:126; 14:35
- Yabahaye amatwi, amaso, n’imitima; ntimushima cyane. (وَجَعَلَ لَكُمُ السَّمْعَ وَالْأَبْصَارَ وَالْأَفْئِدَةَ قَلِيلًا مَّا تَشْكُرُونَ) 32:9; 67:23
- Abajya impaka ku bimenyetso bya Allah, nta gihamya babonye. (الَّذِينَ يُجَادِلُونَ فِي آيَاتِ اللَّهِ بِغَيْرِ سُلْطَانٍ أَتَاهُمْ) 40:35; 40:56
- Nimukurikize idini rya Ibrahimu wibangukiye, kandi ntabwo yari mu bapagani. (فَاتَّبِعُوا مِلَّةَ إِبْرَاهِيمَ حَنِيفًا وَمَا كَانَ مِنَ الْمُشْرِكِينَ) 3:95; 16:123
- Twabakijije mu ngo za Farawo, babarenganyaga n’ibihano bibi. (وَإِذْ أَنجَيْنَاكُم مِّنْ آلِ فِرْعَوْنَ يَسُومُونَكُمْ سُوءَ الْعَذَابِ) 7:141; 14:6
- Iryo ni idini ritagororotse, ariko abantu benshi ntibabizi. (ذَلِكَ الدِّينُ الْقَيِّمُ وَلَكِنَّ أَكْثَرَ النَّاسِ لَا يَعْلَمُونَ) 12:40; 30:30
- Ese ntureba ko Allah yabahaye ubushobozi bwo gukoresha ibiri mu. (أَلَمْ تَرَ أَنَّ اللَّهَ سَخَّرَ لَكُم مَّا فِي) 22:65; 31:20
- Abahakana bavuga bati: Iki si ikindi keretse uburozi bugaragara. (لَقَالَ الَّذِينَ كَفَرُوا إِنْ هَذَا إِلَّا سِحْرٌ مُّبِينٌ) 6:7; 11:7
- Iyo basomewe ibimenyetso byacu bigaragara, abahakana baravuga. (وَإِذَا تُتْلَى عَلَيْهِمْ آيَاتُنَا بَيِّنَاتٍ قَالَ الَّذِينَ كَفَرُوا) 19:73; 46:7
- Ubusitani bwa Edeni butembwamo n’inzuzi, bazabamo ubuziraherezo. (جَنَّاتُ عَدْنٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا) 20:76; 98:8
- Arema uwo ashaka; kandi Allah ni Ushobora byose. (مَا يَشَاءُ إِنَّ اللَّهَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ) 24:45; 35:1
- Kugira ngo abababarira ibyaha byanyu, akabaha igihe kigereranyijwe. (لِيَغْفِرَ لَكُم مِّن ذُنُوبِكُمْ وَيُؤَخِّرَكُمْ إِلَى أَجَلٍ مُّسَمًّى) 14:10; 71:4
- Murashaka kutubuza ibyo ba sekuru bacu basengaga? (تُرِيدُونَ أَن تَصُدُّونَا عَمَّا كَانَ يَعْبُدُ آبَاؤُنَا) 14:10; 34:43
- Ubwo Nyagasani wawe yabwiraga abamarayika ngo: Mu by’ukuri, ngiye kurema umuntu mu ibumba. (وَإِذْ قَالَ رَبُّكَ لِلْمَلَائِكَةِ إِنِّي خَالِقٌ بَشَرًا مِّن) 15:28; 38:71
- Ni We utuma imiyaga ihinduka inkuru nziza, imbere y’impuhwe ze. (وَهُوَ الَّذِي يُرْسِلُ الرِّيَاحَ بُشْرًا بَيْنَ يَدَيْ رَحْمَتِهِ) 7:57; 25:48
- Vuga ngo: Nimugende ku isi, murebe uko iherezo ryagenze. (قُلْ سِيرُوا فِي الْأَرْضِ فَانظُرُوا كَيْفَ كَانَ عَاقِبَةُ) 27:69; 30:42
- Mu by’ukuri, mu kurema ijuru n’isi, no gutandukanya ijoro n’amanywa (hari ibimenyetso). (إِنَّ فِي خَلْقِ السَّمَاوَاتِ وَالْأَرْضِ وَاخْتِلَافِ اللَّيْلِ وَالنَّهَارِ) 2:164; 3:190
- Ni nde utanga inguzanyo nziza kuri Allah, ngo ayibare ku bwa we? (مَّن ذَا الَّذِي يُقْرِضُ اللَّهَ قَرْضًا حَسَنًا فَيُضَاعِفَهُ) 2:245; 57:11
- Ubwo ucurire urubanza hagati yabo, nk’uko Allah yamanuye, kandi ntukurikize ibyifuzo byabo. (فَاحْكُم بَيْنَهُم بِمَا أَنزَلَ اللَّهُ وَلَا تَتَّبِعْ أَهْوَاءَهُمْ) 5:48; 5:49
- Ese bategereje ikindi keretse ko abamarayika bazabageraho, cyangwa itegeko rya Nyagasani wawe rizabageraho? (هَلْ يَنظُرُونَ إِلَّا أَن تَأْتِيَهُمُ الْمَلَائِكَةُ أَوْ يَأْتِيَ) 6:158; 16:33
- Mu by’ukuri, abahimbira Allah ikinyoma, ntibazatsinda. (إِنَّ الَّذِينَ يَفْتَرُونَ عَلَى اللَّهِ الْكَذِبَ لَا يُفْلِحُونَ) 10:69; 16:116
- Nk’uko byagendekeye abantu ba Farawo n’abababanjirije, bahakanye ibimenyetso byacu. (كَدَأْبِ آلِ فِرْعَوْنَ وَالَّذِينَ مِن قَبْلِهِمْ كَذَّبُوا بِآيَاتِنَا) 3:11; 8:54
- Kandi abagezaho inkuru nziza abemera bakora ibyiza, ko bazabona ibihembo. (وَيُبَشِّرُ الْمُؤْمِنِينَ الَّذِينَ يَعْمَلُونَ الصَّالِحَاتِ أَنَّ لَهُمْ أَجْرًا) 17:9; 18:2
- Allah araguriza ngo agabanyirize amafunguro uwo ashaka mu bagaragu be. (اللَّهَ يَبْسُطُ الرِّزْقَ لِمَن يَشَاءُ مِنْ عِبَادِهِ وَيَقْدِرُ) 28:82; 29:62
- Kandi muzasubizwa kwa Uzi ibitagaragara n’ibigaragara, ababwire ibyo mwakoraga. (وَسَتُرَدُّونَ إِلَى عَالِمِ الْغَيْبِ وَالشَّهَادَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ) 9:105; 62:8
- Kandi abo bafitanye isano, bamwe barushije abandi mu gitabo cya Allah. (وَأُولُو الْأَرْحَامِ بَعْضُهُمْ أَوْلَى بِبَعْضٍ فِي كِتَابِ اللَّهِ) 8:75; 33:6
cmds - Commands, Exhortations, Prohibitions, Instructions
- fard / wajib (فرض / واجب) — itegeko (bigomba gukorwa; kwirengagiza ni icyaha)
- mustahabb / mandub (مستحب / مندوب) — bishishikarizwa (bihembwa niba bikozwe, nta cyaha niba birengagijwe)
- mubah (مباح) — biraemewe / bigenga (nta bihembo cyangwa icyaha)
- makruh (مكروه) — birababaza (ntibishimangirwa, ariko nta cyaha niba bikozwe)
- haram (حرام) — birabujijwe (ikozwe ni icyaha)
- halal (حلال, biraemewe / mu mategeko) — bikubiyemo mubah na mustahabb — ibintu byose bitabujijwe
